#include <locale>
void locales(const std::locale& l,const std::ctype<char>& ct,const std::codecvt<wchar_t,char,std::mbstate_t>& cv,const std::numpunct<char>& np,const std::collate<char>& co,char* buf){std::has_facet<std::ctype<char> >(l);std::use_facet<std::ctype<char> >(l);l.name();std::locale::classic();ct.toupper('a');ct.toupper(buf,buf+3);ct.tolower('A');ct.tolower(buf,buf+3);ct.widen('a');ct.widen(buf,buf+3,buf);ct.narrow('a','?');ct.narrow(buf,buf+3,'?',buf);cv.encoding();cv.always_noconv();cv.max_length();np.decimal_point();np.thousands_sep();np.grouping();np.truename();np.falsename();co.compare(buf,buf+3,buf,buf+3);co.transform(buf,buf+3);co.hash(buf,buf+3);}
